values.headerCss:
.first-tier {
  height: 80px;
  margin-bottom: 0px;
  background-color: #005e95;
}

.first-tier .nav > li > a {
  margin-top: 5px;
  padding: 3px 6px;
  color: #fff;
}

.first-tier .nav > li > a:focus,
.first-tier .nav>li>a:hover {
  background-color: #136fbf;
  color: #fff;
}

.first-tier .site-logo img {
  vertical-align: middle;
}

.first-tier h1 {
  display: inline;
  font-size: 25px;
}

.second-tier {
  margin-bottom: 0px;
  background-color: #05466c;
}

.site-header .navbar-header img {
  vertical-align: middle;
  height: 50px;
  padding: 5px;
}

@media (max-width: 768px) {
  .first-tier {
    height: 100px;
  }
}

@media (max-width: 498px) {
  .navbar-brand {
    padding: 0px;
  }
}

.navbar-inverse .navbar-toggle {
  border-color: #ffffff;
}

.navbar-inverse .navbar-toggle:hover {
  background-color: transparent;
}

.navbar-inverse .navbar-toggle .icon-bar {
  background-color: #ffffff;
}

values.footerCss:
.footer-background {
  padding-top: 20px;
  padding-bottom: 20px;
  background-color: #fcfcfc;
}

.logo, .nav {
  margin-bottom: 10px;
}

.nav-pills {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
}

values.headerSass:
.custom-header {
  .panel-container-main {
  /* controls the layout of the panel that contains the accordion */
  background-color: transparent;
  margin-bottom: 5px;
}
.panel-title {
  font-size: 13px; /*font-weight: bold;*/
  color: #ffffff;
}
.accordion-icon {
  fill: #ffffff;
}
#accordion-01 > .panel-body {
  display: flex !important;
  flex-direction: row !important;
  padding-bottom: 5px !important;
  padding-top: 10px !important;
  padding-left: 40px !important;
  padding-right: 40px !important;
}
.mass-custom-accordion-header-header-seal {
  height: 20px;
  width: 20px;
  margin-top: -4px;
  margin-right: 5px;
  object-fit: contain;
}
.mass-custom-accordion-header-img {
  width: auto;
  height: 36px;
  display: inline-block;
}
.mass-custom-accordion-header-text {
  font-size: 14px;
  color: #fff;
  margin-top: 4px;
  margin-bottom: 2px;
}
.mass-custom-accordion-header-title {
  font-weight: bold;
}
.mass-custom-accordion-header-desc {
  font-size: 13px;
} /* Mobile or smaller screens */
@media only screen and (max-width: 899px) {
  .mass-custom-accordion-header-contain {
    width: 100%;
    margin-top: 8px;
  }
  .mass-custom-accordion-header-img {
    margin-top: 12px;
  }
  /*.accordion-panel-main {*/
  /*  width: 110%;*/
  /*}*/
} /* Desktop or wider screens */
@media only screen and (min-width: 900px) {
  .mass-custom-accordion-header-contain {
    display: flex;
    flex-direction: row;
    flex: 1;
  }
  .mass-custom-accordion-header-subcontain {
    display: flex;
    flex-direction: column;
    padding: 0px 24px 0px 12px;
  }
}

